function widget(node, name) { return (node.widgets || []).find((item) => item.name === name); }
function linkedStoryModelConfig(node) {
    const input = (node.inputs || []).find((item) => item.name === "模型接口");
    if (input?.link == null) return null;
    const graph = node.graph || app.graph;
    const link = graph?.links?.get?.(input.link) || graph?.links?.[input.link] || app.graph?.links?.get?.(input.link) || app.graph?.links?.[input.link];
    const originId = link?.origin_id ?? link?.originId;
    const source = graph?.getNodeById?.(originId) || app.graph?.getNodeById?.(originId);
    if (!source || String(source.comfyClass || source.type || "") !== "XiantuStoryModelLora") return null;
    const read = (name, fallback = "") => widget(source, name)?.value ?? fallback;
    let loras = [];
    try { const value = JSON.parse(String(read("lora_stack", "[]"))); if (Array.isArray(value)) loras = value; } catch {}
    return { model_name: String(read("model_name", "")), context_length: Number(read("context_length", 32768)), gpu_layers: Number(read("gpu_layers", 99)), loras };
}
