function blankShot(index = 0) { return { id: uid(), selected: false, title: shotName(index), scene: "场次 01", media_type: "图片关键帧", duration: 3, shot_size: "中景", camera_angle: "平视", camera_movement: "固定镜头", status: "待生成", characters: "", location: "", action: "", dialogue: "", positive: "", negative: "", notes: "", assets: [], source_beat_ids: [], protagonist_refs: [], supporting_refs: [], prop_refs: [], scene_ref: "", video_mode: "图生视频", video_reason: "", reference_requirements: [], first_frame_asset_refs: [], last_frame_asset_refs: [], multi_reference_asset_refs: [], first_frame_prompt: "", last_frame_prompt: "", video_prompt: "", active_image_task_id: "", image_results: {}, result: null }; }
